"Design":"Изглед",
"Design als Datei":"Дизајн као датотека",
"Design exportiert":"Дизајн извезен",
"Design geladen – mit „Übernehmen“ wird es wirksam.":"Дизајн учитан – постаје активан помоћу „Примени“.",
"Design nicht gefunden.":"Дизајн није пронађен.",
"Design, Farben, Symbole, Form und Schrift in einer Datei – zum Weitergeben oder für einen anderen Rechner":"Дизајн, боје, симболи, облик и писмо у једној датотеци – за прослеђивање или за други рачунар",
"Designs suchen":"Тражи дизајне",
"Detail":"Детаљ",
"Detail hinzufügen":"Додај детаљ",
"Dezimalpunkt immer (X10.)":"Увек децимална тачка (X10.)",
"Dezimalpunkt immer schreiben (X10.)":"Увек писати децималну тачку (X10.)",
