"Ein gerollter Rand über 350° schließt sich zum Rohr – das ist so nicht herstellbar":"Заролана ивица преко 350° затвара се у цев – то се овако не може израдити",
"Ein geschlossenes Netz in einen Volumenkörper umwandeln (jedes Dreieck wird eine Fläche)":"Претвори затворену мрежу у запреминско тело (сваки троугао постаје површ)",
"Ein runder Fräser lässt in jeder Innenecke seinen Radius stehen – ein eckiges Gegenstück passt dann nicht hinein. Der Freistich fährt an jeder scharfen Innenecke kurz in die Ecke und zurück.{0}{1}":"Округло глодало оставља свој радијус у сваком унутрашњем углу – угаони противдео тада не стане. Одмак се на сваком оштром унутрашњем углу накратко увлачи у угао и враћа.{0}{1}",
"Ein verbundener Agent arbeitet am geöffneten Entwurf: Er liest und ändert die Zeitachse, fragt Körper, Volumen und Fehler ab, holt Normteile aus dem Bauteilkatalog, lässt sich ein Bild der Ansicht geben, exportiert STEP oder STL, legt Werkzeuge und Fertigungsoperationen an und gibt das NC-Programm aus – das vor dem ersten Schnitt zu prüfen bleibt. Auf Dateien, Einstellungen und andere Entwürfe hat er keinen Zugriff. Jede Änderung ist ein Schritt, den Strg+Z zurücknimmt.":"Повезани агент ради на отвореном нацрту: чита и мења временску линију, упитује тела, запремину и грешке, преузима стандардне делове из каталога делова, добија слику приказа, извози STEP или STL, креира алате и производне операције и исписује NC програм – који се и даље мора проверити пре првог реза. Нема приступ датотекама, подешавањима ни другим нацртима. Свака промена је један корак који Ctrl+Z поништава.",
"Ein zweiter Klick auf die Schaltfläche des Zeichenwerkzeugs schaltet zurück auf Auswählen":"Други клик на дугме алата за цртање враћа на Избор",
