"Erhebung braucht zwei Skizzen mit geschlossenen Profilen auf verschiedenen Ebenen.":"Loft захтева две скице са затвореним профилима на различитим равнима.",
"Erhebung braucht zwei Skizzen mit je einer Kurve (auf verschiedenen Ebenen).":"Loft захтева две скице са по једном кривом (на различитим равнима).",
"Erhebung nicht möglich – Querschnitte prüfen (je ein geschlossenes Profil, nicht verdreht)":"Лофт није могућ – проверите пресеке (по један затворени профил, незаокренут)",
"Erhebung nicht möglich – je Skizze eine Kurve, gleiche Richtung, nicht verdreht":"Лофт није могућ – једна крива по скици, исти смер, незаокренуто",
