"Fläche am bewegten Körper gewählt":"Површ на покретном телу изабрана",
"Fläche anklicken – die Bohrung entsteht mit":"Кликните површ – рупа настаје истовремено",
"Fläche anklicken: an jedem Klickpunkt entsteht die Durchgangsbohrung für die Schraube (ISO 273, Reihe mittel) durch alle Teile, die dort aufeinanderliegen – für Senkschrauben mit 90°-Senkung, für Zylinderschrauben auf Wunsch mit Senkbohrung (DIN 974-1, Reihe 1) so tief wie der Kopf. Die Schraube sitzt gleich darin. Bohrung und Schraube lassen sich danach im Verlauf ändern.":"Кликните површ: у свакој тачки клика настаје пролазна рупа за шраф (ISO 273, средњи низ) кроз све делове који тамо леже један на другом – за шрафове са упуштеном главом са 90° конусним упуштањем, за шрафове са цилиндричном главом по жељи са цилиндричним упуштањем (DIN 974-1, низ 1) дубоким колико и глава. Шраф одмах седи у рупи. Рупа и шраф се после могу мењати на временској линији.",
"Fläche eines Körpers anklicken: ihr Rand kommt als Kontur in die Skizze. Eine Kante anklicken projiziert nur diese Kante (Kreise bleiben Kreise). Projizierte Geometrie ist violett.":"Кликните површ тела: њен руб улази у скицу као контура. Клик на ивицу пројектује само ту ивицу (кругови остају кругови). Пројектована геометрија је љубичаста.",
"Fläche ersetzen":"Замени површ",
"Fläche ersetzen: eine ebene Fläche auf eine andere Ebene legen – der Körper wächst oder wird gekürzt":"Замени површ: постави равну површ на другу раван – тело расте или се скраћује",
"Fläche extrudieren":"Izvlačenje površi",
"Fläche hinter den Fenstern – gilt, wenn oben das Design „Eigenes“ gewählt ist":"Површина иза прозора – важи када је изнад изабран дизајн „Сопствени“",
"Fläche löschen":"Обриши површ",
"Fläche löschen: Bohrungen, Taschen, Verrundungen oder Fasen entfernen – die Nachbarflächen schließen die Lücke":"Обриши површ: уклони рупе, џепове, заобљења или скошења – суседне површи затварају празнину",
"Fläche mit Loch":"Površ sa rupom",
