"Fusion-360-Dateien (.f3d) sind ein geschlossenes Autodesk-Format und können nicht gelesen werden.\n\nIn Fusion 360: Datei → Exportieren → STEP (.stp) wählen und diese Datei hier importieren.":"Fusion 360 датотеке (.f3d) су затворени Autodesk формат и не могу се читати.\n\nУ Fusion 360: изаберите Датотека → Извези → STEP (.stp) и увезите ту датотеку овде.",
"Fusion-360-Postprozessor „{0}“ übernommen:\n\n• {1}":"Постпроцесор Fusion 360 „{0}“ преузет:\n\n• {1}",
"Fährt alle scharfen Außenkanten ab, die von oben erreichbar sind, und bricht sie um die Entgrattiefe – mit dem Fasenfräser als Fase (Werkzeugachse senkrecht, Spitze außerhalb der Kante), mit dem Kugel-/Lollipop-Fräser gerundet.":"Прелази све оштре спољне ивице доступне одозго и ломи их за дубину скидања срха – глодалом за скошење као скошење (оса алата окомита, врх изван ивице), кугластим/lollipop глодалом заобљено.",
"Führungszapfen-Ø":"Ø водећег чепа",
