"Für Sweep wird ein Pfad gebraucht: offene Linie in einer Skizze (mit Enter beenden).":"За Sweep је потребна путања: отворена линија у скици (завршите тастером Enter).",
"Für Touchpads: Scrollen verschiebt die Ansicht, Auseinanderziehen (oder Strg + Mausrad) zoomt":"За тачпед: скроловање помера поглед, раздвајање прстију (или Ctrl + точкић миша) зумира",
"Für V-Gravur einen Fasenfräser (V) wählen":"За V-гравирање изаберите глодало за скошење (V)",
