"Für eine Bohrung Ø {0} mm gibt es in dieser Reihe keine passende Schraube.":"За рупу Ø {0} mm у овој серији нема одговарајућег шрафа.",
"Für schräge Richtungen eine Konstruktionsachse anlegen (durch zwei Punkte, einen Zylinder oder zwei Ebenen) – sie erscheint dann hier als Richtung.":"За косе смерове креирајте конструкциону осу (кроз две тачке, цилиндар или две равни) – она се тада појављује овде као смер.",
"Für wirbelndes Fräsen entlang einer Linie die Nutbreite angeben":"За трохоидално глодање дуж линије унесите ширину жљеба",
"Für {0} ist kein Gewinde hinterlegt.":"За {0} није сачуван навој.",
