"Gemeinsame Schnittkanten nur einmal schneiden":"Заједничке ивице реза сећи само једном",
"Gemeinsame Schnittkanten: liegen zwei Zuschnitte genau eine Schnittfuge auseinander (beim Schachteln als Abstand die Schnittfuge eintragen), fällt ihre Bahn auf der gemeinsamen Kante zusammen und wird nur einmal geschnitten. Der Anschnitt liegt nie in einem Nachbarteil: ist neben einer Kontur kein freier Abfall, wird auf der Kontur eingestochen. Nach „Vorschau“ zeigt ein Bild je Tafel die Bahn, bevor die Dateien gespeichert werden.":"Заједничке ивице реза: ако су два комада удаљена тачно за једну ширину реза (при слагању упишите ширину реза као размак), њихова се путања на заједничкој ивици поклапа и сече се само једном. Улаз у рез никад не лежи у суседном делу: ако поред контуре нема слободног отпада, пробија се на контури. После „Прегледа“ слика за сваку таблу приказује путању пре чувања датотека.",
