"Gespeichert werden Blechdicke {0} mm, Biegeradius innen {1} mm und K-Faktor {2}. Die Regel steht danach bei jedem Blech in der Liste „Blechregel“ – auch in anderen Projekten auf diesem Rechner.":"Чува се дебљина лима {0} mm, унутрашњи полупречник савијања {1} mm и K-фактор {2}. Правило ће након тога бити на листи „Правило за лим“ код сваког лима – и у другим пројектима на овом рачунару.",
