"Gewindebohrung im untersten Teil":"Рупа са навојем у најдоњем делу",
"Gewindebohrung im untersten Teil: die Durchgangsbohrung endet, wo das unterste Teil beginnt; dort entsteht das Kernloch mit Gewinde – drei Gewindegänge tiefer, als die Schraube reicht, oder durch das ganze Teil. Liegt nur ein Teil unter dem Punkt, bekommt es das Gewinde von der Fläche an. „Länge passend zur Einschraubtiefe“ nimmt die nächste Länge der Reihe, mit der die Schraube etwa so tief im Gewinde sitzt, wie ihr Gewinde dick ist (Richtwert für Stahl) – aber nie länger, als das Teil dick ist.":"Рупа са навојем у најдоњем делу: пролазна рупа се завршава где почиње најдоњи део; ту настаје рупа за навој са навојем – три навоја дубље него што завртањ досеже или кроз цео део. Ако се испод тачке налази само један део, навој добија од површи надаље. „Дужина према дубини увртања“ узима следећу дужину из низа којом завртањ седи у навоју отприлике онолико дубоко колико је дебео његов навој (оријентациона вредност за челик) – али никад дуже него што је део дебео.",
"Gewindebohrung {0} – Einschraubtiefe nur {1} mm":"рупа са навојем {0} – дубина увртања само {1} mm",
"Gewindebohrung {0}, Einschraubtiefe {1} mm":"рупа са навојем {0}, дубина увртања {1} mm",
"Gewindebohrung: gebohrt wird das Kernloch; das Gewinde erscheint als Gewindedarstellung am Modell und mit seinem Namen in der Zeichnung.":"Рупа са навојем: буши се рупа за језгро; навој се приказује као симболични навој на моделу и са својим називом на цртежу.",
