"Gleiche Durchmesser ergeben ein Rohr, verschiedene einen Kegelstumpf. Die Abwicklung wird auf der neutralen Faser gerechnet (Innenfläche + K-Faktor × Blechdicke); beim Runden liegt sie näher an der Blechmitte als beim Abkanten – üblich ist ein K-Faktor von 0,45 bis 0,5. Mit einer Blechregel gelten deren Dicke und K-Faktor. Der Nahtspalt bleibt am größeren Durchmesser offen (0 = stumpf gestoßen, im Körper dann ein Schlitz von 0,01 mm).":"Једнаки пречници дају цев, различити зарубљену купу. Развијени облик се рачуна на неутралном влакну (унутрашња површ + K-фактор × дебљина лима); код ваљања лежи ближе средини лима него код савијања на преси – уобичајен K-фактор је од 0,45 до 0,5. Са правилом за лим важе његова дебљина и K-фактор. Размак шава остаје отворен на већем пречнику (0 = сучељено, у телу тада прорез од 0,01 mm).",
"Gleicher Abstand":"Једнако растојање",
"Gleichlauf":"Истосмерно",
"Gleichmäßige Dreiecke dieser Größe: lange Kanten werden geteilt, danach wird auf die Dreieckszahl eines gleichmäßigen Netzes reduziert. Gut vor dem Glätten oder Formen von Scans.":"Уједначени троуглови ове величине: дуге ивице се деле, затим се смањује на број троуглова уједначене мреже. Добро пре заглађивања или обликовања скенова.",
