"Halbzeug: Nennmaße der Norm, auf jede Länge zugeschnitten. Nicht jede Paarung von Maß und Wanddicke ist bei jedem Händler am Lager. Ein Rohr entlang einer Skizzenlinie – auch um Ecken und Bögen – legt der Befehl „Rohr“ an.":"Полупроизвод: називне мере према норми, исечен на било коју дужину. Није свака комбинација мере и дебљине зида на залихи код сваког добављача. Цев дуж линије скице – и око углова и лукова – прави наредба „Цев“.",
