"Heidenhain: an der Steuerung die Datenübertragung über Ethernet freigeben (wie für TNCremo, LSV2, Port 19000); Standardordner TNC 640 TNC:\\nc_prog\\, iTNC 530 TNC:\\. FTP: Port 21, Ordner z. B. /_N_WKS_DIR oder /NC. Netzwerkordner: Pfad wie \\\\MASCHINE\\NC oder Z:\\NC. DNC: Wandler als TCP-Server (raw), meist Port 4001; an der Steuerung „Abarbeiten extern“, DNC oder TAPE starten.":"Heidenhain: на управљачкој јединици омогућите пренос података преко Етернета (као за TNCremo, LSV2, порт 19000); подразумевани фолдер TNC 640 TNC:\\nc_prog\\, iTNC 530 TNC:\\. FTP: порт 21, фолдер нпр. /_N_WKS_DIR или /NC. Мрежни фолдер: путања попут \\\\MASCHINE\\NC или Z:\\NC. DNC: претварач као TCP сервер (raw), обично порт 4001; на управљачкој јединици покрените „Спољно извршавање“, DNC или TAPE.",
