"Im Spiegelbild läuft das Werkzeug andersherum: aus Gleichlauf wird dort Gegenlauf. Die Radiuskorrektur der Steuerung wechselt die Seite mit.":"У огледалној слици алат иде обрнуто: истосмерно глодање тамо постаје супротносмерно. Корекција радијуса управљања такође мења страну.",
