"In diese Bibliothek kann nicht eingefügt werden – Dokument oder eigene Bibliothek wählen.":"У ову библиотеку није могуће уметати – изаберите документ или сопствену библиотеку.",
"In diesem Setup sind Spannmittel gewählt: dann bleibt es beim vollständigen Rückzug.":"У овом сетапу су изабрана стезна средства: тада остаје потпуно повлачење.",
