"J (relativ)":"J (релативно)",
"JSON kopieren":"Копирај JSON",
"Je Operation zwei Q-Parameter am Programmanfang: der erste verschiebt die Tiefe (DL, + = weniger tief), der zweite das seitliche Aufmaß (DR, + = mehr Aufmaß; wirkt nur bei Radiuskorrektur an der Steuerung RL/RR). An der Maschine eine Zahl ändern statt Sätze suchen.":"Два Q-параметра по операцији на почетку програма: први помера дубину (DL, + = мање дубоко), други бочни додатак (DR, + = већи додатак; делује само уз корекцију радијуса у управљачкој јединици RL/RR). На машини промените један број уместо да тражите блокове.",
"Je Skizze die erste Kurve – offen oder geschlossen. Die Kurven werden mit einer Haut verbunden (Fläche ohne Dicke).":"Прва крива сваке скице – отворена или затворена. Криве се повезују омотачем (површ без дебљине).",
"Je Tafel eine Datei. Die Bahn läuft um die halbe Schnittfuge (beim Fräsen den halben Fräser) neben dem Umriss im Abfall; Ausschnitte kommen vor dem Umriss ihres Teils, jede Kontur beginnt mit einem Anschnitt aus dem Abfall. Kiemenschlitze werden auf ihrer Linie geschnitten. Haltestege: so viele Stellen je Umriss bleiben stehen (Laser, Plasma, Wasserstrahl: der Strahl setzt dort aus; Fräsen: der Fräser hebt auf halbe Blechdicke), Umrisse unter 40 mm Länge bekommen keine. „Steuerung“ legt fest, womit der Strahl ein- und ausgeschaltet wird; die Einstechzeit steht als G4 im Programm, außer die Steuerung sticht selbst ein. Nullpunkt ist die linke untere Ecke der Tafel, beim Fräsen Z0 die Blechoberseite. Das Programm vor dem Einsatz an der Maschine oder in einem NC-Simulator prüfen.":"Једна датотека по табли. Путања иде у отпаду уз контуру, на пола ширине реза (код глодања пола глодала); изрези долазе пре контуре свог дела, а свака контура почиње улазом у рез из отпада. Жалузине се секу по својој линији. Придржни мостићи: толико места по контури остаје непресечено (ласер, плазма, водени млаз: млаз се ту искључује; глодање: глодало се подиже на пола дебљине лима); контуре краће од 40 mm немају их. „Управљање“ одређује чиме се млаз укључује и искључује; време пробијања у програму стоји као G4, осим ако управљање само пробија. Нулта тачка је доњи леви угао табле, код глодања је Z0 горња страна лима. Програм проверите на машини или у NC симулатору пре употребе.",
"Je Werkzeug alle Teile (weniger Werkzeugwechsel)":"Сви делови по алату (мање измена алата)",
"Jede Achse einzeln: Kante, Ecke, Fläche oder Bohrung anklicken. Nicht gesetzte Achsen kommen vom Rohteilpunkt.":"Свака оса посебно: кликните ивицу, угао, површ или рупу. Осе које нису постављене преузимају се из тачке припремка.",
"Jede Bohrung wird mit ihren Koordinaten einzeln angefahren (X/Y je Bohrung) – kein Lochkreis- oder Rastermuster.":"Свака рупа се појединачно наводи својим координатама (X/Y по рупи) – без узорка круга рупа или мреже.",
"Jede Operation als Unterprogramm (LBL) am Programmende, Aufruf mit CALL LBL":"Свака операција као потпрограм (LBL) на крају програма, позив са CALL LBL",
"Jeder Kreis der Skizze ist ein Bohrungsmittelpunkt. Gebohrt wird entgegen der Skizzennormalen (ins Material).":"Сваки круг скице је центар рупе. Бушење иде супротно од нормале скице (у материјал).",
"Jeder Kreis der Skizze wird um die Mitte (in Skizzenkoordinaten) gedreht wiederholt – ein Kreis im Abstand des Teilkreisradius ergibt einen Lochkreis.":"Сваки круг скице понавља се ротиран око центра (у координатама скице) – круг на растојању полупречника подеоног круга даје кружни распоред рупа.",
"Jeder Kreis der Skizze wird zum Raster: Abstände in X und Y der Skizze (auch negativ).":"Сваки круг скице постаје мрежа: размаци по X и Y скице (и негативни).",
"Jeder sichtbare Körper wird ein Glied mit Netz (STL, in Metern), Masse und Trägheit, jedes Gelenk ein Gelenk mit Achse und Grenzen. Die jetzige Stellung ist die Nullstellung. Mit einem Paketnamen stehen die Netze im URDF als package://Name/meshes/…, sonst als relativer Pfad.":"Свако видљиво тело постаје карика са мрежом (STL, у метрима), масом и инерцијом, сваки зглоб зглоб са осом и границама. Тренутни положај је нулти положај. Са називом пакета мреже у URDF-у стоје као package://Name/meshes/…, иначе као релативна путања.",
"Jedes # im Skizzentext wird durch die Nummer ersetzt, mit Nullen aufgefüllt (SN-#### → SN-{0}). Bei mehreren Teilen in einer Aufspannung bekommt jedes Teil die nächste Nummer: {1}{2}.":"Сваки # у тексту скице замењује се бројем допуњеним нулама (SN-#### → SN-{0}). Код више делова у једном стезању сваки део добија следећи број: {1}{2}.",
"Jedes Teil hat seinen eigenen Nullpunkt in der Steuerung (G54, G55 … bzw. Bezugspunkt-Nummer in der Tabelle – Heidenhain Zyklus 247). Alle Nullpunkte vorher an der Maschine setzen.":"Сваки део има сопствену нулту тачку у управљачкој јединици (G54, G55 … односно број референтне тачке у табели – Heidenhain циклус 247). Све нулте тачке претходно поставите на машини.",
"Jedes eigene Maß und jeder Toleranzrahmen bekommt eine Nummer in einem Kreis. Die Liste enthält Nennmaß, Toleranz, Höchst- und Mindestmaß und Felder für den Istwert. Maße ohne eigene Toleranz bekommen die Allgemeintoleranz.":"Свака сопствена мера и сваки оквир толеранције добијају број у кругу. Листа садржи називну меру, толеранцију, највећу и најмању меру и поља за стварну вредност. Мере без сопствене толеранције добијају општу толеранцију.",
