"Kalibrieren: zwei Punkte im Bild anklicken, deren Abstand bekannt ist, und den wirklichen Abstand eingeben – das Bild bekommt den richtigen Maßstab.":"Калибрација: кликните на две тачке на слици чије је растојање познато и унесите стварно растојање – слика добија исправну размеру.",
