"Kante {0}: Lasche an einer gebogenen Kante – ihr Rand wird beim Umformen um {1} % gestaucht (Faltengefahr); der Zuschnitt ist dort eine Näherung.":"Ивица {0}: прирубница на закривљеној ивици – њена се ивица при обликовању сабија за {1} % (опасност од набора); развијени облик је ту апроксимација.",
"Kante {0}: Lasche an einer gebogenen Kante – ihr Rand wird beim Umformen um {1} % gestreckt (Rissgefahr); der Zuschnitt ist dort eine Näherung.":"Ивица {0}: прирубница на закривљеној ивици – њена се ивица при обликовању развлачи за {1} % (опасност од прслина); развијени облик је ту апроксимација.",
"Kante {0}: das Laschenmaß {1} mm ist kleiner als die Biegung ({2} mm)":"Ивица {0}: мера прирубнице {1} mm мања је од савијања ({2} mm)",
