"Kante {0}: die Lasche liegt in einer Biegezone":"Ивица {0}: прирубница лежи у зони савијања",
"Kante {0}: ein Ausschnitt gehört zu einer Lasche, die es nicht gibt.":"Ивица {0}: изрез припада прирубници која не постоји.",
"Kante {0}: ein Ausschnitt in der Lasche liegt {1} mm neben der Biegung (weniger als 2 × Blechdicke) – er verzieht sich beim Biegen.":"Ивица {0}: изрез у прирубници налази се {1} mm поред савијања (мање од 2 × дебљина лима) – деформише се при савијању.",
"Kante {0}: ein Ausschnitt liegt {1} mm neben der Biegung (weniger als 2 × Blechdicke) – er verzieht sich beim Biegen.":"Ивица {0}: изрез је {1} mm од савијања (мање од 2 × дебљина лима) – искривиће се при савијању.",
"Kante {0}: ein Ausschnitt ragt über die Lasche hinaus.":"Ивица {0}: изрез вири изван прирубнице.",
