"Kante {0}{1}: geschlossener Saum (Innenradius {2} mm) – wird in zwei Hüben gebogen und zugedrückt; harte Werkstoffe reißen dabei an der Außenseite.":"Ивица {0}{1}: затворени преклоп (унутрашњи полупречник {2} mm) – савија се у два хода и стишће; тврди материјали при том пуцају на спољашњој страни.",
