"Kanten anklicken zum Hinzufügen oder Entfernen – das Ergebnis erscheint gleich im Modell. Kanten, die vor dem Befehl angeklickt wurden, sind schon gewählt. Eingabe = OK.":"Кликните ивице да их додате или уклоните – резултат се одмах приказује на моделу. Ивице кликнуте пре наредбе већ су изабране. Enter = У реду.",
