"Kappe loslassen und „Nullpunkt kalibrieren“ wählen. Danach jede Richtung ausprobieren: der Balken soll sich bewegen, in Ruhe in der grauen Totzone bleiben.":"Отпустите капицу и изаберите „Калибриши нулту тачку“. Затим испробајте сваки смер: трака треба да се помера, а у мировању да остане у сивој мртвој зони.",
"Kappe schieben = verschieben, drücken/ziehen = zoomen, kippen und drehen = Modell drehen. In Skizzen nur Verschieben und Zoomen. SpaceMouse Pro/Enterprise: T, F, R = Ansicht oben, vorne, rechts. Falls nichts passiert: 3Dconnexion-Treiber kurz beenden und neu verbinden.":"Померање капице = померање, притисак/повлачење = зумирање, нагињање и окретање = ротирање модела. У скицама само померање и зумирање. SpaceMouse Pro/Enterprise: T, F, R = поглед одозго, спреда, здесна. Ако се ништа не догоди: накратко затворите 3Dconnexion драјвер и поново се повежите.",
