"Kollisionsform: die konvexe Hülle hat wenige Dreiecke und rechnet in der Simulation schnell, füllt aber Taschen und Bohrungen; der Quader ist am gröbsten. Die Ansicht behält immer das volle Netz.":"Облик судара: конвексни омотач има мало троуглова и брзо се рачуна у симулацији, али попуњава џепове и рупе; квадар је најгрубљи. Поглед увек задржава целу мрежу.",
