"Kontur mit {0} Punkten – Okuma: G85 (LAP) mit Kontur G81…G80, Fanuc: G71 P…Q…. Die Steuerung schruppt mit ihrer eigenen Aufteilung; die Simulation hier ist die WerkFab-Bahn.":"Контура са {0} тачака – Okuma: G85 (LAP) са контуром G81…G80, Fanuc: G71 P…Q…. Управљање грубо обрађује сопственом поделом; симулација овде је WerkFab путања.",
"Kontur zum Freifräsen davor anlegen":"Претходно додати контуру за ослобађање глодањем",
"Kontur {0}":"Контура {0}",
"Konturauswahl":"Избор контура",
"Konturen außen und innen":"Спољашње и унутрашње контуре",
"Konturen folgen dem Rand der dunklen Flächen. Die Mittellinie läuft in der Mitte der Striche – passend für Gravuren und Strichzeichnungen. „Geraden, Bögen und Kreise“ erkennt gerade Kanten, scharfe Ecken, Rundungen und Kreise; „Linienzüge“ folgt dem Bild Punkt für Punkt. Den Maßstab danach bei Bedarf mit „Vorlage kalibrieren“ oder „Skalieren“ anpassen.":"Контуре прате ивицу тамних површина. Средишња линија иде по средини потеза – погодно за гравуре и линијске цртеже. „Линије, лукови и кругови“ препознаје праве ивице, оштре углове, заобљења и кругове; „Полилиније“ прате слику тачку по тачку. Размеру затим по потреби прилагодите опцијом „Калибриши шаблон“ или „Скалирај“.",
"Konturen mit Radiuskorrektur an der Steuerung (RL/RR) fahren mit APPR/DEP an und ab; die Steuerung berechnet Hilfspunkt und Korrektur selbst":"Контуре са корекцијом полупречника на управљању (RL/RR) прилазе и одлазе са APPR/DEP; управљање само израчунава помоћну тачку и корекцију",
