"Lasche an Lasche: Winkel + biegt in dieselbe Richtung weiter (U-Profil, Falz mit 180°), − in die Gegenrichtung (Z-Stufe, Hutprofil). Saum: der Rand der Lasche wird um 180° auf sich selbst zurückgelegt – offen mit einem Spalt von einer Blechdicke, geschlossen flach zugedrückt; mit − 180° liegt er auf der anderen Seite. Das Feld R ist der Innenradius nur dieser Biegung (leer = wie beim Blech). Für einen Saum direkt an der Plattenkante die Lasche selbst auf 180° stellen. Kröpfung: zwei Biegungen gegeneinander (− 45° und + 45°) – der Rand läuft parallel versetzt weiter; Versatz über die Länge des schrägen Stücks und die Winkel.":"Преклопник на преклопнику: угао + савија даље у истом смеру (U-профил, пречка од 180°), − у супротном смеру (Z-степеница, профил шешира). Преклоп: ивица преклопника пресавија се за 180° на саму себе – отворени са размаком од једне дебљине лима, затворени спљоштено стиснут; са − 180° лежи на другој страни. Поље R је унутрашњи полупречник само овог савијања (празно = као код лима). За преклоп директно на ивици плоче поставите сам преклопник на 180°. Степенасто савијање: два савијања једно према другом (− 45° и + 45°) – ивица се наставља паралелно померена; померај произилази из дужине косог комада и углова.",
"Lasche {0}":"Прирубница {0}",
