"Länge L ist die Messlänge aus dem Werkzeug (Nennwert). Die echten Längen an der Maschine oder am Voreinstellgerät messen und eintragen. Heidenhain: Datei nach TNC:\\system\\tooltab kopieren, dann Werkzeugverwaltung → WERKZEUG IMPORT.":"Дужина L је мерна дужина алата (називна вредност). Стварне дужине измерите на машини или на уређају за претподешавање и унесите их. Heidenhain: копирајте датотеку у TNC:\\system\\tooltab, затим Управљање алатима → TOOL IMPORT.",
