"Macht ein geschlossenes Netz hohl: eine Innenwand im Abstand der Wandstärke kommt dazu – spart Material und Druckzeit. Stellen, die dünner sind als zwei Wandstärken, überschneiden sich danach; für Harzdruck ein Ablaufloch mit „Boolesch“ abziehen.":"Издубљује затворену мрежу: додаје се унутрашњи зид на удаљености дебљине зида – штеди материјал и време штампе. Места тања од две дебљине зида се након тога преклапају; за штампу смолом одузмите одводну рупу помоћу „Булова“.",
