"Materialien über „Darstellung“ (A) auf die Körper ziehen. Beim In-Canvas-Rendern wird das Bild mit jedem Durchgang glatter (weiche Schatten, saubere Kanten); jede Kamerabewegung beginnt neu.":"Превуците материјале на тела преко „Приказ“ (A). При рендеровању на платну слика постаје глатка са сваким пролазом (меке сенке, чисте ивице); свако померање камере почиње изнова.",
