"Mehrere aneinanderhängende Kanten zählen als eine Strecke: Der Radius läuft vom Anfang der Kette bis zu ihrem Ende, Stützpunkte gelten in % der ganzen Kettenlänge. Das rechnet der große Geometriekern.":"Више повезаних ивица рачуна се као једна деоница: полупречник се мења од почетка низа до његовог краја, контролне тачке важе у % целе дужине низа. То рачуна велико геометријско језгро.",
"Mehrfachaufspannung":"Вишеструко стезање",
"Mehrfachaufspannung: Nullpunkt von Teil {0} gibt es an dieser Steuerung nicht – nur ein Teil ausgegeben":"Вишеструко стезање: ова управљачка јединица нема нулту тачку за део {0} – излаз само за један део",
"Mehrfachaufspannung: Nullpunktverschiebung gibt es in diesem Postprozessor nicht – „Eigener Nullpunkt je Teil“ wählen; nur ein Teil ausgegeben":"Вишеструко стезање: овај постпроцесор нема померање нулте тачке – изаберите „Посебна нулта тачка за сваки део“; излаз само за један део",
