"Meine Werkzeuge":"Моји алати",
"Meldet Bahnen, die tiefer schneiden als das Modell an dieser Stelle (Schaft-, Plan-, Kugel- und Torusfräser, Fasenfräser und Bohrer mit ihrem Kegel; 3-Achs-Bewegungen). Ein Schnitt, der nicht im Modell steht – Gravur, Eckenfreistich, Tasche nur aus einer Skizze – wird ebenfalls gemeldet.":"Пријављује путање које секу дубље од модела на том месту (прстасти, чеони, кугласти и торусни глодачи, глодала за скошење и бургије са својим конусом; 3-осна кретања). Пријављује се и рез којег нема у моделу – гравирање, растерећење угла, џеп само из скице.",
