"Normteil: Punkt auf einer ebenen Fläche anklicken – dort entsteht die Bohrung.":"Стандардни део: кликните тачку на равној површи – тамо настаје рупа.",
"Normteil: {0} eingefügt – weitere Bohrung anklicken oder beenden.":"Стандардни део: {0} уметнут – кликните следећу рупу или завршите.",
"Normteil: {0} eingefügt – weiteren Punkt anklicken oder beenden.":"Стандардни део: {0} уметнут – кликните следећу тачку или завршите.",
