"Prägung {0}: {1} mm ist höher als 3 × Blechdicke – mit senkrechter Wand reißt das Blech.":"Утисак {0}: {1} mm је веће од 3 × дебљина лима – са усправним зидом лим пуца.",
"Prägung: die Kontur wird nicht ausgeschnitten, sondern um die Höhe aus der Platte gedrückt; das zweite Feld ist die Wandschräge (0° = senkrecht). Senkprägung: der Rand einer runden Bohrung wird zu einem 90°-Kegel gedrückt – für Senkschrauben in dünnem Blech (− nach unten: Schraube von oben).":"Утисак: контура се не изрезује, већ се за задату висину утискује из плоче; друго поље је угао зида (0° = управно). Упуштени утисак: руб округле рупе утискује се у конус од 90° – за упуштене завртње у танком лиму (− надоле: завртањ одозго).",
