"Tauchschruppen: senkrechte Tauchgänge Reihe für Reihe – für lange Werkzeuge und tiefe Kavitäten":"Груба обрада урањањем: вертикално урањање ред по ред – за дугачке алате и дубоке шупљине",
"Teil 1 liegt normalerweise auf dem Nullpunkt (0, 0, 0). Die anderen werden mit einer Nullpunktverschiebung angefahren (Heidenhain Zyklus 7, Fanuc/LinuxCNC G52, Sinumerik TRANS). Vor jedem Wechsel geht das Werkzeug auf die sichere Höhe.":"Део 1 се обично налази у нултој тачки (0, 0, 0). До осталих се долази померањем нулте тачке (Heidenhain циклус 7, Fanuc/LinuxCNC G52, Sinumerik TRANS). Пре сваког прелаза алат одлази на безбедну висину.",
