"Toleranzart":"Врста толеранције",
"Toleranzwert, dahinter die Bezüge (durch Leerzeichen getrennt), z. B. Ø0,05 A B. Zusätze in Klammern werden als Buchstabe im Kreis gezeichnet: Ø0,05(M) A(M) – (M) Maximum-Material, (L) Minimum-Material, (P) projiziert, (F) freier Zustand, (E) Hüllbedingung":"Вредност толеранције, иза ње базе (одвојене размаком), нпр. Ø0,05 A B. Додаци у заградама цртају се као слово у кругу: Ø0,05(M) A(M) – (M) максимум материјала, (L) минимум материјала, (P) пројектовано, (F) слободно стање, (E) услов омотача",
