"Verrechnet zwei geschlossene Netze wirklich miteinander: innen liegende Flächen verschwinden, die Schnittkanten werden neu vernetzt. Gerechnet wird nur dort, wo sich die beiden Netze begegnen können – ein großes Netz mit einem kleinen Eingriff geht deshalb schnell. Überlappen zwei große Netze ganz, vorher „Reduzieren“.":"Стварно међусобно израчунава две затворене мреже: унутрашње површи нестају, ивице пресека се поново умрежавају. Рачуна се само тамо где се две мреже могу срести – велика мрежа са малим захватом стога је брза. Ако се две велике мреже потпуно преклапају, пре тога „Смањи“.",
