"Wickelt die Skizzenkurven auf den Zylinder: X bleibt X, der Abstand quer zur Achse wird zum Bogen auf dem Abwicklungs-Ø (Drehung A). Die Skizze muss parallel zur A-Achse liegen, z. B. auf einer Tangentialebene. Gefräst wird in fester Tiefe unter der Teiloberfläche – für Gravuren, Schriften und Nuten rund um das Teil.":"Намотава кривуље скице на цилиндар: X остаје X, удаљеност попречно на осу постаје лук на Ø развоја (ротација A). Скица мора лежати паралелно са A осом, нпр. на тангенцијалној равни. Глође се на сталној дубини испод површине дела – за гравирање, натписе и уторе око дела.",
"Wie 3D-Kontur, aber das Werkzeug fährt ohne Absätze kontinuierlich nach unten – keine Eintauchmarken an steilen Wänden.":"Као 3D контура, али алат континуирано иде наниже без степеника – нема трагова урањања на стрмим зидовима.",
"Wie Einfahrt":"Као увлачење",
