"Wie die Ansicht":"Као приказ",
"Wie die Ansicht (alle Dreiecke)":"Као поглед (сви троуглови)",
"Wie fein Körper für STL, 3MF und den Slicer in Dreiecke zerlegt werden: Abweichung von der wahren Fläche als Anteil der Körpergröße. Netze bleiben, wie sie sind.":"Колико фино се тела за STL, 3MF и Slicer раздвајају на троуглове: одступање од праве површине као удео величине тела. Мреже остају какве јесу.",
"Wie fein Zylinder, Kugeln und Rundungen in der Ansicht aus Dreiecken bestehen. Feiner sieht runder aus, rechnet bei großen Modellen aber länger. Der Export hat eine eigene Einstellung (3D-Druck).":"Колико фино се цилиндри, лопте и заобљења у приказу састоје од троуглова. Финије изгледа обло, али код великих модела дуже траје прорачун. Извоз има сопствено подешавање (3D штампа).",
"Wie im System":"Као у систему",
