"Zungen stehen am freien Ende der Lasche über und kommen in den Zuschnitt. „Schlitze als Skizze“ legt die passenden Schlitze dort an, wo die Zungen stehen – je Ebene eine Skizze, jeder Schlitz ringsum um das Spiel größer als die Zunge. In dieser Skizze den Umriss des Gegenstücks zeichnen und daraus ein Blech oder eine Extrusion machen: die Schlitze werden Ausschnitte. Das Gegenstück liegt auf den Laschenenden auf; die Zungenlänge ist üblich gleich seiner Dicke.":"Језичци вире на слободном крају преклопника и улазе у кројење. „Утори као скица“ креира одговарајуће уторе тамо где језичци стоје – по једну скицу за раван, сваки утор је са свих страна већи од језичка за зазор. У овој скици нацртајте обрис парног дела и од њега направите лим или екструзију: утори постају исечци. Парни део належе на крајеве преклопника; дужина језичка је обично једнака његовој дебљини.",
